INSERT INTO `categories` (`id`, `name`, `slug`, `icon`, `color`, `description`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1,'Vegetables','vegetables','carrot','#E2552C','Roots, gourds and everything for the handi.',0,1,'2026-09-27 12:54:04','2026-09-27 12:54:04'),(2,'Fruits','fruits','mango','#F2B33D','Orchard-ripe, never cold-stored for months.',1,1,'2026-09-27 12:54:04','2026-09-27 12:54:04'),(3,'Herbs & Greens','herbs-greens','herb','#6FA35B','Picked at dawn, on your table by noon.',2,1,'2026-09-27 12:54:04','2026-09-27 12:54:04'),(4,'Dairy & Eggs','dairy-eggs','glass_of_milk','#8DB8D8','Fresh milk, butter, cheese and free-range eggs.',3,1,'2026-09-27 12:54:04','2026-09-27 12:54:04'),(5,'Baked Goods','baked-goods','bread','#C98B4E','Sourdough, kulcha and bakes from local ovens.',4,1,'2026-09-27 12:54:04','2026-09-27 12:54:04'),(6,'Honey & Preserves','honey-preserves','honey_pot','#E0A526','Raw honey, jams, pickles and achar.',5,1,'2026-09-27 12:54:04','2026-09-27 12:54:04'),(7,'Grains & Pulses','grains-pulses','sheaf_of_rice','#B5A26A','Heritage rice, daals and nuts.',6,1,'2026-09-27 12:54:04','2026-09-27 12:54:04'),(8,'Flowers','flowers','sunflower','#D96C8C','Seasonal stems and bouquets.',7,1,'2026-09-27 12:54:04','2026-09-27 12:54:04');
