INSERT INTO `markets` (`id`, `name`, `slug`, `description`, `address`, `city`, `latitude`, `longitude`, `map_provider`, `operating_days`, `opens_at`, `closes_at`, `cover_image`, `is_active`, `created_at`, `updated_at`) VALUES (1,'Qasimabad Sunday Farmers Market','qasimabad-sunday-farmers-market','Hyderabad’s best-loved Sunday market: seasonal produce, artisan bread and live cooking along Qasimabad’s main road.','Main Qasimabad Road, near Naseem Nagar Chowk, Hyderabad, Sindh','Qasimabad',25.40560000,68.32650000,'openstreetmap','[0]','08:00:00','14:00:00','photo:qasimabad-sunday-farmers-market',1,'2026-09-27 12:54:04','2026-09-27 12:54:13'),(2,'Latifabad Organic Bazaar','latifabad-organic-bazaar','A weekend bazaar focused on pesticide-free growers, raw honey and small-batch dairy.','Unit No. 7, near Latifabad Sports Complex, Hyderabad, Sindh','Latifabad',25.37020000,68.36830000,'openstreetmap','[6,0]','09:00:00','15:00:00','photo:latifabad-organic-bazaar',1,'2026-09-27 12:54:04','2026-09-27 12:54:13'),(3,'Hirabad Evening Harvest Market','hirabad-evening-harvest-market','An evening market with string lights, fresh-cut flowers and farm-to-table snacks.','Hirabad Chowk, off Liaquat Colony Road, Hyderabad, Sindh','Hirabad',25.40150000,68.37460000,'openstreetmap','[5,6]','16:00:00','21:00:00','photo:hirabad-evening-harvest-market',1,'2026-09-27 12:54:04','2026-09-27 12:54:13'),(4,'Auto Bhan Greens Market','auto-bhan-greens-market','Early-morning greens and vegetables straight from the farms of Tando Jam and Hatri.','Auto Bhan Road, near Sindh Museum, Hyderabad, Sindh','Auto Bhan Road',25.38760000,68.34750000,'openstreetmap','[3,0]','07:00:00','13:00:00','photo:auto-bhan-greens-market',1,'2026-09-27 12:54:04','2026-09-27 12:54:13'),(5,'Paretabad Farmers Mela','paretabad-farmers-mela','Three evenings a week of fruit, eggs and pantry staples for the families of old Hyderabad.','Paretabad, near Pakka Qila Road, Hyderabad, Sindh','Paretabad',25.41390000,68.38220000,'openstreetmap','[2,4,6]','16:00:00','21:00:00','photo:paretabad-farmers-mela',1,'2026-09-27 12:54:04','2026-09-27 12:54:13'),(6,'Saddar Heritage Produce Market','saddar-heritage-produce-market','Hyderabad’s historic produce hub, open six days a week a few steps from the Shahi Bazaar.','Near Shahi Bazaar, Saddar, Hyderabad, Sindh','Saddar',25.39250000,68.36890000,'openstreetmap','[1,2,3,4,5,6]','07:00:00','19:00:00','photo:saddar-heritage-produce-market',1,'2026-09-27 12:54:04','2026-09-27 12:54:13'),(7,'Tando Jam Countryside Market','tando-jam-countryside-market','Where the orchards and dairies around Tando Jam meet the city — mangoes, guavas and fresh milk.','Near Sindh Agriculture University gate, Tando Jam, Hyderabad, Sindh','Tando Jam',25.42810000,68.53920000,'openstreetmap','[4,0]','07:00:00','12:00:00','photo:tando-jam-countryside-market',1,'2026-09-27 12:54:04','2026-09-27 12:54:13');
